/*
Theme Name: ICF Ede
Theme URI: https://icfede.nl
Author: ICF Ede
Description: Warm, eigentijds blokthema voor de Interculturele Christelijke Familie Ede. Met foto's, meertalig en RTL-klaar.
Requires at least: 6.6
Tested up to: 6.8
Requires PHP: 7.4
Version: 1.3.0
License: GNU General Public License v2 or later
License URI: https://www.gnu.org/licenses/gpl-2.0.html
Text Domain: icf-ede
*/

/* ---------- Basis ---------- */
html { scroll-behavior: smooth; scroll-padding-top: 90px; }
body { -webkit-font-smoothing: antialiased; }
:where(a) { text-underline-offset: .18em; text-decoration-thickness: 1px; }
:where(a:hover) { text-decoration-thickness: 2px; }
:focus-visible { outline: 3px solid var(--wp--preset--color--honing); outline-offset: 3px; border-radius: 4px; }
:where(h1, h2, h3) { text-wrap: balance; }

/* Klein label boven een kop */
.icf-label {
	font-size: .78rem !important; font-weight: 700; letter-spacing: .12em; text-transform: uppercase;
	color: var(--wp--preset--color--terracotta); margin-bottom: .4rem !important;
}

/* ---------- Header: vast bovenaan, licht doorschijnend ---------- */
.wp-site-blocks > header:first-child,
.wp-site-blocks > .wp-block-template-part:first-child { position: sticky; top: 0; z-index: 50; }
.admin-bar .wp-site-blocks > header:first-child,
.admin-bar .wp-site-blocks > .wp-block-template-part:first-child { top: 32px; }
@media (max-width: 782px) { .admin-bar .wp-site-blocks > header:first-child { top: 0; } }
.icf-header {
	background: color-mix(in srgb, var(--wp--preset--color--room) 86%, transparent);
	-webkit-backdrop-filter: saturate(1.4) blur(14px); backdrop-filter: saturate(1.4) blur(14px);
	border-bottom: 1px solid color-mix(in srgb, var(--wp--preset--color--koffie) 8%, transparent);
}
.icf-header .wp-block-site-logo img { width: 52px; height: auto; }
.icf-header .wp-block-navigation a { font-weight: 600; }
.icf-header .wp-block-navigation a:hover { color: var(--wp--preset--color--terracotta); }

/* ---------- Taalbalk (bovenaan elke pagina) ---------- */
.icf-taalbalk-nav { display: flex; align-items: center; justify-content: center; gap: .6rem; flex-wrap: wrap; }
.icf-taalbalk-nav .icf-wereld { flex: none; color: var(--wp--preset--color--honing); }
.icf-taalbalk-nav ul { list-style: none; display: flex; flex-wrap: wrap; justify-content: center; gap: .35rem; margin: 0; padding: 0; }
.icf-taalbalk-nav a {
	display: inline-block; padding: .3rem .85rem; border-radius: 999px; line-height: 1.3;
	color: var(--wp--preset--color--room); text-decoration: none; font-weight: 600; font-size: .95rem;
	border: 1px solid rgb(255 255 255 / .28); transition: background .15s, color .15s;
}
.icf-taalbalk-nav a:hover { background: rgb(255 255 255 / .14); }
.icf-taalbalk-nav a.is-actief { background: var(--wp--preset--color--honing); border-color: var(--wp--preset--color--honing); color: var(--wp--preset--color--koffie); }
.icf-taalbalk-nav a:lang(fa), .icf-taalbalk-nav a:lang(ar) { font-family: Tahoma, 'Segoe UI', 'Noto Sans Arabic', sans-serif; font-size: 1rem; }
@media (max-width: 480px) {
	/* Alle vier de talen moeten altijd zichtbaar blijven: liever twee regels dan een taal die buiten beeld valt. */
	.icf-taalbalk-nav { gap: .4rem; }
	.icf-taalbalk-nav .icf-wereld { width: 16px; height: 16px; }
	.icf-taalbalk-nav ul { gap: .25rem; flex-wrap: wrap; }
	.icf-taalbalk-nav a { padding: .25rem .55rem; font-size: .82rem; }
	.icf-taalbalk-nav a:lang(fa), .icf-taalbalk-nav a:lang(ar) { font-size: .88rem; }
}
@media (max-width: 360px) { .icf-taalbalk-nav .icf-wereld { display: none; } }

/* ---------- Hero (fotobanner) ---------- */
.icf-hero .wp-block-cover__image-background { animation: icf-zoom 18s ease-out both; }
@keyframes icf-zoom { from { transform: scale(1.08); } to { transform: scale(1); } }
.icf-hero.wp-block-cover {
	padding-inline: max(var(--wp--preset--spacing--40), calc((100% - 1200px) / 2)) !important;
}
.icf-hero .wp-block-cover__inner-container { width: 100% !important; max-width: 1200px; }
.icf-hero .wp-block-cover__inner-container > * { margin-inline-start: 0 !important; margin-inline-end: auto !important; }
.icf-hero .icf-label { color: var(--wp--preset--color--honing); }
.icf-hero .icf-hero-titel { color: #fff; max-width: 13ch; margin-top: 0; }
.icf-hero .icf-hero-tekst { color: rgb(255 255 255 / .9); max-width: 46ch; }
.icf-hero .icf-volgende { background: rgb(255 255 255 / .12); -webkit-backdrop-filter: blur(10px); backdrop-filter: blur(10px); border: 1px solid rgb(255 255 255 / .22); width: fit-content; max-width: 100%; }
.icf-licht .wp-block-button__link { color: #fff !important; border-color: rgb(255 255 255 / .7) !important; }
.icf-licht .wp-block-button__link:hover { background: #fff !important; color: var(--wp--preset--color--koffie) !important; }

/* ---------- Foto's ---------- */
.icf-foto { margin: 0; overflow: hidden; border-radius: 22px; }
.icf-foto img { display: block; width: 100%; height: 100%; object-fit: cover; transition: transform .6s cubic-bezier(.2,.7,.2,1); }
.icf-foto-staand img { aspect-ratio: 4 / 5; }
.icf-foto-breed img { aspect-ratio: 3 / 2; }
.icf-stap:hover .icf-foto img,
.icf-kaart:hover .icf-foto img { transform: scale(1.04); }

/* Zo ziet een zondag eruit: genummerde stappen */
.icf-stappen { counter-reset: stap; }
.icf-stap { counter-increment: stap; }
.icf-stap h3::before {
	content: counter(stap); display: inline-grid; place-items: center; width: 1.7em; height: 1.7em; margin-inline-end: .5em;
	border-radius: 50%; background: var(--wp--preset--color--terracotta); color: #fff; font-size: .8em; vertical-align: .1em;
}
.icf-stap h3 { margin-top: 1rem; }
.icf-stap p { color: color-mix(in srgb, var(--wp--preset--color--koffie) 78%, transparent); }

/* ---------- Missie (foto + tekst) ---------- */
.icf-missie { border-radius: 28px; overflow: hidden; background: var(--wp--preset--color--olijf); color: var(--wp--preset--color--room); }
.icf-missie .wp-block-media-text__content { padding: clamp(1.5rem, 5vw, 4rem) !important; }
.icf-missie h2 { color: #fff; }
.icf-missie .icf-label { color: var(--wp--preset--color--honing); }
.icf-missie a { color: var(--wp--preset--color--honing); font-weight: 600; }
.icf-missie .wp-block-media-text__media { min-height: 360px; }

/* ---------- Visie, missie, kernwaarden (getekende illustraties) ---------- */
.icf-illustratie img { display: block; width: 100%; max-width: 320px; height: auto; margin-inline: auto; }
.icf-wvs { padding: clamp(1.75rem, 5vw, 4rem); }
.icf-wvs-kaarten { gap: var(--wp--preset--spacing--40) !important; margin-top: var(--wp--preset--spacing--40); }
.icf-wvs-kaart { background: rgb(255 255 255 / .07); border-radius: 22px; padding: 1.5rem 1.5rem 1.75rem; text-align: center; }
.icf-wvs-kaart .icf-illustratie img { max-width: 210px; }
.icf-wvs-kaart h3 { color: #fff; margin-top: 1rem; }
.icf-wvs-kaart p { margin-top: .4rem; }
.icf-wvs-link { margin-top: var(--wp--preset--spacing--40); text-align: center; }
.icf-beeld-sectie { gap: var(--wp--preset--spacing--50) !important; margin-block: var(--wp--preset--spacing--50) !important; }
@media (min-width: 782px) {
	.icf-beeld-sectie + .icf-beeld-sectie { flex-direction: row-reverse; }
	.icf-beeld-sectie + .icf-beeld-sectie + .icf-beeld-sectie { flex-direction: row; }
}
.icf-waarden { gap: var(--wp--preset--spacing--40) !important; margin-top: var(--wp--preset--spacing--40) !important; }
.icf-waarde {
	background: var(--wp--preset--color--wit); border-radius: 22px; padding: 1.5rem 1.5rem 1.6rem;
	box-shadow: 0 1px 2px rgb(43 33 28 / .05), 0 12px 32px rgb(43 33 28 / .07);
}
.icf-waarde-icoon img { display: block; width: 76px; height: auto; }
.icf-waarde h3 { margin-top: .9rem; }
.icf-waarde p { font-size: .98rem; }

/* ---------- Kaarten ---------- */
.icf-kaart {
	background: var(--wp--preset--color--wit); border-radius: 22px; overflow: hidden;
	box-shadow: 0 1px 2px rgb(43 33 28 / .05), 0 12px 32px rgb(43 33 28 / .07);
	display: flex; flex-direction: column;
}
.icf-kaart .icf-foto { border-radius: 0; }
.icf-kaart-tekst { padding: 1.4rem 1.5rem 1.6rem; flex: 1; display: flex; flex-direction: column; }
.icf-kaart-tekst h3 { margin-top: 0; }
.icf-kaart-tekst .icf-pijl { margin-top: auto; padding-top: .5rem; font-weight: 600; }
.icf-pijl a { text-decoration: none; }

/* ---------- Bijeenkomsten (plugin-output) ---------- */
.icf-volgende {
	display: flex; flex-wrap: wrap; gap: .25rem 1rem; align-items: baseline;
	background: var(--wp--preset--color--olijf); color: var(--wp--preset--color--room);
	padding: 1rem 1.25rem; border-radius: 16px; margin: 0;
}
.icf-volgende a { color: inherit; }
.icf-volgende strong { color: var(--wp--preset--color--honing); text-transform: uppercase; letter-spacing: .08em; font-size: .78rem; }
.icf-volgende .icf-volgende-datum { font-family: var(--wp--preset--font-family--koppen); font-weight: 700; font-size: 1.3rem; }

.icf-rooster { list-style: none; margin: 0; padding: 0; display: grid; gap: .6rem; }
.icf-rooster li {
	display: grid; grid-template-columns: 4.2rem 1fr; gap: 1rem; align-items: center;
	background: var(--wp--preset--color--wit); border-radius: 16px; padding: .8rem 1rem;
	border-inline-start: 5px solid var(--wp--preset--color--terracotta);
	transition: transform .2s ease;
}
.icf-rooster li:first-child { box-shadow: 0 10px 28px rgb(43 33 28 / .08); }
.icf-rooster li:hover { transform: translateX(4px); }
.icf-rooster li.is-afwijkend { border-inline-start-color: var(--wp--preset--color--honing); }
.icf-rooster .icf-dag { text-align: center; line-height: 1.05; }
.icf-rooster .icf-dag b { display: block; font-family: var(--wp--preset--font-family--koppen); font-size: 1.8rem; color: var(--wp--preset--color--terracotta); }
.icf-rooster .icf-dag span { font-size: .76rem; text-transform: uppercase; letter-spacing: .06em; }
.icf-rooster .icf-info { display: flex; flex-direction: column; gap: .1rem; min-width: 0; }
.icf-rooster .icf-tijd { font-weight: 700; }
.icf-rooster .icf-plek, .icf-rooster .icf-plek a { color: inherit; opacity: .8; font-size: .92rem; }
.icf-rooster .icf-opm { display: inline-block; width: fit-content; background: color-mix(in srgb, var(--wp--preset--color--honing) 30%, transparent); padding: .05rem .5rem; border-radius: 6px; font-size: .82rem; font-weight: 600; }
.icf-leeg { opacity: .7; font-style: italic; }

/* ---------- Geven ---------- */
.icf-qr { background: var(--wp--preset--color--wit); padding: 12px; border-radius: 16px; width: 168px; height: 168px; display: block; }

/* ---------- Footer ---------- */
.icf-footer a { color: var(--wp--preset--color--room); }
.icf-footer .icf-klein { font-size: .85rem; opacity: .75; }

/* ---------- Klein scherm ---------- */
@media (max-width: 781px) {
	.icf-stappen { display: grid !important; grid-template-columns: 1fr 1fr; }
	.icf-foto-staand img { aspect-ratio: 1 / 1; }
	.icf-missie .wp-block-media-text__media { min-height: 240px; }
}
@media (max-width: 600px) {
	.icf-rooster li { grid-template-columns: 3.4rem 1fr; gap: .75rem; }
	.icf-rooster .icf-dag b { font-size: 1.45rem; }
	.icf-hero { min-height: 560px !important; }
}
@media (max-width: 600px) {
	.icf-stappen { gap: 1rem 0.75rem !important; }
	.icf-stap h3 { font-size: 1.05rem; }
	.icf-stap p { font-size: .92rem; }
}

/* ---------- Farsi en Arabisch (rechts naar links) ---------- */
:lang(fa) body, body:lang(fa), :lang(ar) body, body:lang(ar) {
	font-family: Tahoma, 'Segoe UI', 'Noto Sans Arabic', 'Noto Naskh Arabic', system-ui, sans-serif;
	line-height: 1.85;
}
:lang(fa) :where(h1, h2, h3, .wp-block-site-title), :lang(ar) :where(h1, h2, h3, .wp-block-site-title),
:lang(fa) .icf-volgende-datum, :lang(ar) .icf-volgende-datum {
	font-family: 'Segoe UI', Tahoma, 'Noto Sans Arabic', system-ui, sans-serif;
	letter-spacing: 0 !important; line-height: 1.35;
}
/* Arabisch schrift is aaneengeschreven: geen letterspatiëring of hoofdletters */
:lang(fa) .icf-label, :lang(ar) .icf-label,
:lang(fa) .icf-volgende strong, :lang(ar) .icf-volgende strong,
:lang(fa) .icf-rooster .icf-dag span, :lang(ar) .icf-rooster .icf-dag span {
	letter-spacing: 0; text-transform: none; font-size: .9rem !important;
}
[dir="rtl"] .icf-rooster li:hover { transform: translateX(-4px); }
[dir="rtl"] .icf-hero .icf-hero-titel { max-width: 16ch; }

@media (prefers-reduced-motion: reduce) {
	html { scroll-behavior: auto; }
	.icf-hero .wp-block-cover__image-background { animation: none; }
	.icf-foto img, .icf-rooster li { transition: none; }
}

